def _query_results(collection, embedding, n_results, disaster):
    kwargs = {
        "query_embeddings": [embedding],
        "n_results": n_results,
    }
    if disaster:
        kwargs["where"] = {"disaster": disaster}
    return collection.query(**kwargs)

